-- SQLDiff probes for Db2 for i (IBM i 7.x only).
--
-- GENERATED from probes/db2i/probes.toml by probes/db2i/db2i_probes.py build.
-- Do not edit by hand. Probe set 371e26495f28.
--
-- What it does: creates the schema SQLDFPROBE (CREATE SCHEMA, so its tables are
-- journaled), two tables and about 30 small procedures in it, runs them, and
-- prints one line per result. It touches nothing outside SQLDFPROBE, apart from
-- reading SYSIBMADM.ENV_SYS_INFO, QSYS2.GROUP_PTF_INFO, QSYS2.SYSROUTINES and
-- QSYS2.RECORD_LOCK_INFO, and declaring temporary tables in QTEMP.
--
-- How to run (details in probes/db2i/README.md):
--   ACS Run SQL Scripts, SQL naming: open this file, Run > All. The last result
--   set has one column, SQLDIFF_PROBE_LINE; save or copy all its rows.
--   Run it again at any time: earlier results are deleted first.
--   Remove everything afterwards with: DROP SCHEMA SQLDFPROBE
--
-- The result lines hold SQLSTATEs, counts and Db2 messages about SQLDFPROBE
-- objects, the IBM i release and PTF group levels: no system name, user or
-- data.

-- 1. Setup: schema, tables, logging procedures.
BEGIN
  DECLARE V_IGNORED INTEGER DEFAULT 0;
  DECLARE V_SQL VARCHAR(1000);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_IGNORED = 1;
  SET V_SQL = 'CREATE SCHEMA SQLDFPROBE';
  EXECUTE IMMEDIATE V_SQL;
END;

BEGIN
  DECLARE V_IGNORED INTEGER DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_IGNORED = 1;
  COMMIT;
END;

BEGIN
  DECLARE V_IGNORED INTEGER DEFAULT 0;
  DECLARE V_SQL VARCHAR(1000);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_IGNORED = 1;
  SET V_SQL = 'CREATE TABLE SQLDFPROBE.RESULTS ('
    || 'R_SEQ INTEGER GENERATED ALWAYS AS IDENTITY, '
    || 'R_PROBE VARCHAR(40) NOT NULL, R_STEP VARCHAR(10) NOT NULL, '
    || 'R_STATE CHAR(5), R_CODE INTEGER, R_MSG VARCHAR(2000), '
    || 'R_O_STATE CHAR(5), R_O_CODE INTEGER, R_N1 INTEGER, '
    || 'R_N2 INTEGER, R_TEXT VARCHAR(200))';
  EXECUTE IMMEDIATE V_SQL;
  SET V_SQL = 'CREATE TABLE SQLDFPROBE.T (PRB INTEGER NOT NULL, '
    || 'K INTEGER NOT NULL, V INTEGER, PRIMARY KEY (PRB, K))';
  EXECUTE IMMEDIATE V_SQL;
  SET V_SQL = 'DELETE FROM SQLDFPROBE.RESULTS WITH NC';
  EXECUTE IMMEDIATE V_SQL;
  SET V_SQL = 'DELETE FROM SQLDFPROBE.T WITH NC';
  EXECUTE IMMEDIATE V_SQL;
END;

BEGIN
  DECLARE V_IGNORED INTEGER DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_IGNORED = 1;
  COMMIT;
END;

CREATE OR REPLACE PROCEDURE SQLDFPROBE.LOG_CALL (
    IN P_PROBE VARCHAR(40), IN P_STATE CHAR(5), IN P_CODE INTEGER,
    IN P_MSG VARCHAR(2000), IN P_O_STATE CHAR(5), IN P_O_CODE INTEGER,
    IN P_N1 INTEGER, IN P_N2 INTEGER, IN P_TEXT VARCHAR(200))
  LANGUAGE SQL
  MODIFIES SQL DATA
  SET OPTION COMMIT = *NONE
BEGIN
  INSERT INTO SQLDFPROBE.RESULTS (R_PROBE, R_STEP, R_STATE, R_CODE, R_MSG,
      R_O_STATE, R_O_CODE, R_N1, R_N2, R_TEXT)
    VALUES (P_PROBE, 'call', P_STATE, P_CODE, P_MSG,
      P_O_STATE, P_O_CODE, P_N1, P_N2, P_TEXT) WITH NC;
END;

CREATE OR REPLACE PROCEDURE SQLDFPROBE.RUN_DDL (
    IN P_PROBE VARCHAR(40), IN P_DROP VARCHAR(200),
    IN P_SQL VARCHAR(16000))
  LANGUAGE SQL
  MODIFIES SQL DATA
  SET OPTION COMMIT = *NONE
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_CODE = 0;
    EXECUTE IMMEDIATE P_DROP;
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
      GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
        V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
    EXECUTE IMMEDIATE P_SQL;
  END;
  INSERT INTO SQLDFPROBE.RESULTS (R_PROBE, R_STEP, R_STATE, R_CODE, R_MSG)
    VALUES (P_PROBE, 'create', V_STATE, V_CODE, V_MSG) WITH NC;
END;

BEGIN
  DECLARE V_IGNORED INTEGER DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET V_IGNORED = 1;
  COMMIT;
END;

BEGIN
  DECLARE V_NO_STATE CHAR(5);
  DECLARE V_NO_N INTEGER;
  CALL SQLDFPROBE.LOG_CALL('META-FORMAT', '00000', 1, 'probe set',
    V_NO_STATE, V_NO_N, V_NO_N, V_NO_N, '371e26495f28');
END;

-- 2. Create the probe procedures. Each create is logged with its SQLSTATE,
-- so a procedure Db2 for i refuses is a result, not a stop.

-- P_HARNESS_NC (probes H-COMMIT-CONTROL)
-- SET OPTION COMMIT = *CS
-- | BEGIN
-- |   SET O_STATE = '00000';
-- |   SET O_CODE = 0;
-- |   DELETE FROM SQLDFPROBE.T WHERE PRB = 1 WITH NC;
-- |   BEGIN
-- |     DECLARE EXIT HANDLER FOR SQLEXCEPTION
-- |       GET DIAGNOSTICS CONDITION 1 O_STATE = RETURNED_SQLSTATE,
-- |         O_CODE = DB2_RETURNED_SQLCODE;
-- |     INSERT INTO SQLDFPROBE.T (PRB, K) VALUES (1, 1) WITH NC;
-- |     INSERT INTO SQLDFPROBE.T (PRB, K) VALUES (1, 2);
-- |     ROLLBACK;
-- |   END;
-- |   SELECT COUNT(*) INTO O_N1 FROM SQLDFPROBE.T WHERE PRB = 1 AND K = 1;
-- |   SELECT COUNT(*) INTO O_N2 FROM SQLDFPROBE.T WHERE PRB = 1 AND K = 2;
-- |   COMMIT;
-- | END
BEGIN
  DECLARE V_SQL VARCHAR(16000);
  SET V_SQL =
       'CREATE OR REPLACE PROCEDURE SQLDFPROBE.P_HARNESS_NC (OUT O_STATE '
    || 'CHAR(5), OUT O_CODE INTEGER, OUT O_N1 INTEGER, OUT O_N2 INTEGER, OUT '
    || 'O_TEXT VARCHAR(200)) LANGUAGE SQL MODIFIES SQL DATA SET OPTION COMMIT '
    || '= *CS BEGIN SET O_STATE = ''00000''; SET O_CODE = 0; DELETE FROM '
    || 'SQLDFPROBE.T WHERE PRB = 1 WITH NC; BEGIN DECLARE EXIT HANDLER FOR '
    || 'SQLEXCEPTION GET DIAGNOSTICS CONDITION 1 O_STATE = RETURNED_SQLSTATE, '
    || 'O_CODE = DB2_RETURNED_SQLCODE; INSERT INTO SQLDFPROBE.T (PRB, K) '
    || 'VALUES (1, 1) WITH NC; INSERT INTO SQLDFPROBE.T (PRB, K) VALUES (1, '
    || '2); ROLLBACK; END; SELECT COUNT(*) INTO O_N1 FROM SQLDFPROBE.T WHERE '
    || 'PRB = 1 AND K = 1; SELECT COUNT(*) INTO O_N2 FROM SQLDFPROBE.T WHERE '
    || 'PRB = 1 AND K = 2; COMMIT; END';
  CALL SQLDFPROBE.RUN_DDL('PROC:HARNESS_NC',
    'DROP PROCEDURE SQLDFPROBE.P_HARNESS_NC', V_SQL);
END;

