-- P_V9_CAST_INT (probes V9-INT-PLAIN, V9-INT-ALPHA, V9-INT-EMPTY,
--     V9-INT-BLANK, V9-INT-PADDED, V9-INT-DECIMAL-TEXT)
-- SET OPTION COMMIT = *NONE
-- | BEGIN
-- |   DECLARE V INTEGER;
-- |   SET O_STATE = '00000';
-- |   SET O_CODE = 0;
-- |   BEGIN
-- |     DECLARE EXIT HANDLER FOR SQLEXCEPTION
-- |       GET DIAGNOSTICS CONDITION 1 O_STATE = RETURNED_SQLSTATE,
-- |         O_CODE = DB2_RETURNED_SQLCODE;
-- |     SET V = CAST(S AS INTEGER);
-- |     SET O_N1 = V;
-- |   END;
-- | END
BEGIN
  DECLARE V_SQL VARCHAR(16000);
  SET V_SQL =
       'CREATE OR REPLACE PROCEDURE SQLDFPROBE.P_V9_CAST_INT (IN S '
    || 'VARCHAR(20), OUT O_STATE CHAR(5), OUT O_CODE INTEGER, OUT O_N1 '
    || 'INTEGER, OUT O_N2 INTEGER, OUT O_TEXT VARCHAR(200)) LANGUAGE SQL '
    || 'MODIFIES SQL DATA SET OPTION COMMIT = *NONE BEGIN DECLARE V INTEGER; '
    || 'SET O_STATE = ''00000''; SET O_CODE = 0; BEGIN DECLARE EXIT HANDLER '
    || 'FOR SQLEXCEPTION GET DIAGNOSTICS CONDITION 1 O_STATE = '
