-- P_V15_KEEP_CS (probes V15-KEEP-CS)
-- SET OPTION COMMIT = *CS
-- | BEGIN
-- |   DECLARE X INTEGER;
-- |   SET O_STATE = '00000';
-- |   SET O_CODE = 0;
-- |   DELETE FROM SQLDFPROBE.T WHERE PRB = 151;
-- |   INSERT INTO SQLDFPROBE.T (PRB, K, V) VALUES (151, 1, 7);
-- |   COMMIT;
-- |   BEGIN
-- |     DECLARE EXIT HANDLER FOR SQLEXCEPTION
-- |       GET DIAGNOSTICS CONDITION 1 O_STATE = RETURNED_SQLSTATE,
-- |         O_CODE = DB2_RETURNED_SQLCODE;
-- |     SELECT V INTO X FROM SQLDFPROBE.T WHERE PRB = 151 AND K = 1
-- |       WITH RS USE AND KEEP EXCLUSIVE LOCKS;
-- |   END;
-- |   BEGIN
-- |     DECLARE EXIT HANDLER FOR SQLEXCEPTION SET O_TEXT = 'lock view failed';
-- |     SELECT COUNT(*), COALESCE(MIN(LOCK_STATE), '') || '/'
-- |         || COALESCE(MAX(LOCK_STATE), '')
-- |       INTO O_N1, O_TEXT FROM QSYS2.RECORD_LOCK_INFO
-- |       WHERE TABLE_SCHEMA = 'SQLDFPROBE' AND TABLE_NAME = 'T';
-- |   END;
-- |   COMMIT;
-- |   BEGIN
-- |     DECLARE EXIT HANDLER FOR SQLEXCEPTION SET O_N2 = -1;
-- |     SELECT COUNT(*) INTO O_N2 FROM QSYS2.RECORD_LOCK_INFO
-- |       WHERE TABLE_SCHEMA = 'SQLDFPROBE' AND TABLE_NAME = 'T';
-- |   END;
-- | END
BEGIN
  DECLARE V_SQL VARCHAR(16000);
  SET V_SQL =
       'CREATE OR REPLACE PROCEDURE SQLDFPROBE.P_V15_KEEP_CS (OUT O_STATE '
    || 'CHAR(5), OUT O_CODE INTEGER, OUT O_N1 INTEGER, OUT O_N2 INTEGER, OUT '
    || 'O_TEXT VARCHAR(200)) LANGUAGE SQL MODIFIES SQL DATA SET OPTION COMMIT '
    || '= *CS BEGIN DECLARE X INTEGER; SET O_STATE = ''00000''; SET O_CODE = '
    || '0; DELETE FROM SQLDFPROBE.T WHERE PRB = 151; INSERT INTO SQLDFPROBE.T '
    || '(PRB, K, V) VALUES (151, 1, 7); COMMIT; BEGIN DECLARE EXIT HANDLER '
    || 'FOR SQLEXCEPTION GET DIAGNOSTICS CONDITION 1 O_STATE = '
    || 'RETURNED_SQLSTATE, O_CODE = DB2_RETURNED_SQLCODE; SELECT V INTO X '
    || 'FROM SQLDFPROBE.T WHERE PRB = 151 AND K = 1 WITH RS USE AND KEEP '
    || 'EXCLUSIVE LOCKS; END; BEGIN DECLARE EXIT HANDLER FOR SQLEXCEPTION SET '
    || 'O_TEXT = ''lock view failed''; SELECT COUNT(*), '
    || 'COALESCE(MIN(LOCK_STATE), '''') || ''/'' || COALESCE(MAX(LOCK_STATE), '
    || ''''') INTO O_N1, O_TEXT FROM QSYS2.RECORD_LOCK_INFO WHERE '
    || 'TABLE_SCHEMA = ''SQLDFPROBE'' AND TABLE_NAME = ''T''; END; COMMIT; '
    || 'BEGIN DECLARE EXIT HANDLER FOR SQLEXCEPTION SET O_N2 = -1; SELECT '
    || 'COUNT(*) INTO O_N2 FROM QSYS2.RECORD_LOCK_INFO WHERE TABLE_SCHEMA = '
    || '''SQLDFPROBE'' AND TABLE_NAME = ''T''; END; END';
  CALL SQLDFPROBE.RUN_DDL('PROC:V15_KEEP_CS',
    'DROP PROCEDURE SQLDFPROBE.P_V15_KEEP_CS', V_SQL);
END;

