-- |       USING (VALUES (1, 10), (2, 20), (2, 21), (3, 30)) AS SRC (K, V)
-- |       ON TGT.PRB = 31 AND TGT.K = SRC.K
-- |       WHEN MATCHED THEN UPDATE SET V = SRC.V;
-- |   END;
-- |   SELECT COUNT(*) INTO O_N1 FROM SQLDFPROBE.T WHERE PRB = 31 AND V <> 0;
-- |   ROLLBACK;
-- | END
