    || '= *CS BEGIN SET O_STATE = ''00000''; SET O_CODE = 0; DELETE FROM '
    || 'SQLDFPROBE.T WHERE PRB = 31; INSERT INTO SQLDFPROBE.T (PRB, K, V) '
    || 'VALUES (31, 1, 0), (31, 2, 0), (31, 3, 0); COMMIT; BEGIN DECLARE EXIT '
