-- 3. Run the probes.

-- H-COMMIT-CONTROL (HARNESS, control): Does a procedure compiled with *CS run
--     under commitment control here, and does a WITH NC insert survive its
--     ROLLBACK? Every *CS control below relies on the first; the result log
--     relies on the second.
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
  DECLARE O_N2 INTEGER;
  DECLARE O_TEXT VARCHAR(200);
