-- ENV-DB2-GROUP (ENV, info): Which Db2 for IBM i PTF group level and
--     Technology Refresh level are installed?
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
  DECLARE O_N2 INTEGER;
  DECLARE O_TEXT VARCHAR(200);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  SELECT MAX(PTF_GROUP_LEVEL) INTO O_N1 FROM QSYS2.GROUP_PTF_INFO
    WHERE PTF_GROUP_DESCRIPTION LIKE 'DB2 FOR IBM I%'
      AND PTF_GROUP_STATUS = 'INSTALLED';
  SELECT MAX(PTF_GROUP_LEVEL) INTO O_N2 FROM QSYS2.GROUP_PTF_INFO
    WHERE PTF_GROUP_DESCRIPTION LIKE '%TECHNOLOGY REFRESH%'
      AND PTF_GROUP_STATUS = 'INSTALLED';
  CALL SQLDFPROBE.LOG_CALL('ENV-DB2-GROUP', V_STATE, V_CODE, V_MSG,
    O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
END;

-- V5-INTERFACE-COMMIT (V5, info): Does the interface that runs this script
--     (ACS Run SQL Scripts, RUNSQLSTM, ...) run top-level statements under
--     commitment control?
BEGIN
  DECLARE V_STATE CHAR(5) DEFAULT '00000';
  DECLARE V_CODE INTEGER DEFAULT 0;
  DECLARE V_MSG VARCHAR(2000) DEFAULT '';
  DECLARE O_STATE CHAR(5);
  DECLARE O_CODE INTEGER;
  DECLARE O_N1 INTEGER;
  DECLARE O_N2 INTEGER;
  DECLARE O_TEXT VARCHAR(200);
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    GET DIAGNOSTICS CONDITION 1 V_STATE = RETURNED_SQLSTATE,
      V_CODE = DB2_RETURNED_SQLCODE, V_MSG = MESSAGE_TEXT;
  DELETE FROM SQLDFPROBE.T WHERE PRB = 52 WITH NC;
  INSERT INTO SQLDFPROBE.T (PRB, K) VALUES (52, 1);
  ROLLBACK;
  SELECT COUNT(*) INTO O_N1 FROM SQLDFPROBE.T WHERE PRB = 52;
  DELETE FROM SQLDFPROBE.T WHERE PRB = 52 WITH NC;
  CALL SQLDFPROBE.LOG_CALL('V5-INTERFACE-COMMIT', V_STATE, V_CODE, V_MSG,
    O_STATE, O_CODE, O_N1, O_N2, O_TEXT);
END;

