-- 4. The results: save or copy every row of this result set.
SELECT 'SQLDFP|1|' || TRIM(CHAR(R_SEQ)) || '|' || R_PROBE
    || '|' || R_STEP
    || '|' || COALESCE(R_STATE, '~')
    || '|' || COALESCE(TRIM(CHAR(R_CODE)), '~')
    || '|' || COALESCE(R_O_STATE, '~')
    || '|' || COALESCE(TRIM(CHAR(R_O_CODE)), '~')
    || '|' || COALESCE(TRIM(CHAR(R_N1)), '~')
    || '|' || COALESCE(TRIM(CHAR(R_N2)), '~')
    || '|' || COALESCE(REPLACE(R_TEXT, '|', '/'), '~')
    || '|' || COALESCE(REPLACE(R_MSG, '|', '/'), '~')
    AS SQLDIFF_PROBE_LINE
  FROM SQLDFPROBE.RESULTS ORDER BY R_SEQ;
